CustomField.formula:
IF( CONTAINS(TEXT(Unit_Category__c), '1'),
    200.00,
    IF( CONTAINS(TEXT(Unit_Category__c), '2'),
        400.00,
        IF( CONTAINS(TEXT(Unit_Category__c), '3'),
            600.00,
            IF( CONTAINS(TEXT(Unit_Category__c), '4'),
                800.00,
                IF( CONTAINS(TEXT(Unit_Category__c), '4.5'),
                    1000.00,
                    1200.00
                )
            )
        )
    )
)
